options.styles:
.pulse-wrap{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,system-ui,sans-serif;color:#F5F5F7;max-width:26rem;margin:0 auto;box-sizing:border-box;min-height:100%;display:flex;flex-direction:column;justify-content:center;padding:1.8rem 1.25rem 1.2rem;text-align:center;-webkit-font-smoothing:antialiased;}
.pulse-state{display:flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:.5em;font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.14em;color:#86868B;font-variant-numeric:tabular-nums;margin-bottom:1.6rem;}
.pulse-state .sep{opacity:.45;}
.pulse-state.stale{color:#FF9F0A;}
.pulse-dot{width:7px;height:7px;border-radius:50%;background:#30D158;box-shadow:0 0 0 4px rgba(48,209,88,.16);}
.pulse-state.stale .pulse-dot{background:#FF9F0A;box-shadow:0 0 0 4px rgba(255,159,10,.16);}
.pulse-state.idle .pulse-dot{background:#8E8E93;box-shadow:0 0 0 4px rgba(142,142,147,.16);}
.pulse-hero{font-size:clamp(3.4rem,17vw,5.4rem);font-weight:600;letter-spacing:-.03em;line-height:1;font-variant-numeric:tabular-nums;}
.pulse-cur{color:#86868B;font-weight:500;font-size:.4em;vertical-align:.42em;margin-right:.05em;}
.pulse-cents{color:#86868B;font-weight:500;font-size:.42em;}
.pulse-pnl{margin-top:1.05rem;font-size:1.05rem;font-variant-numeric:tabular-nums;letter-spacing:-.01em;}
.pulse-pnl .gain{color:#30D158;}
.pulse-pnl .loss{color:#FF453A;}
.pulse-pnl .flat{color:#86868B;}
.pulse-pnl .wk{color:#86868B;margin-left:.7em;}
.pulse-top{padding-bottom:.4rem;}
.pulse-bot{padding-top:.4rem;}
@media (min-width:900px){.pulse-wrap{max-width:32rem;}}
.pulse-rows{border-top:1px solid rgba(242,242,244,.13);text-align:left;}
.pulse-row{display:flex;align-items:baseline;justify-content:space-between;gap:1rem;padding:.9rem .15rem;border-bottom:1px solid rgba(242,242,244,.13);}
.pulse-row:last-child{border-bottom:0;}
.pulse-row .lab{font-size:15px;font-weight:500;color:#F5F5F7;}
.pulse-row .exp{display:block;font-size:15px;font-weight:400;color:#86868B;margin-top:.18rem;}
.pulse-row .val{font-size:17px;font-variant-numeric:tabular-nums;color:#F5F5F7;white-space:nowrap;text-align:right;}
.pulse-row .val .sub{display:block;font-size:11px;font-weight:500;color:#86868B;text-transform:uppercase;letter-spacing:.06em;margin-top:.1rem;}
.pulse-foot{margin-top:1.4rem;font-size:11px;color:#6E6E73;text-transform:uppercase;letter-spacing:.1em;}

